<script setup lang="ts">
/**
 * List.Item: one item: a title, with a leading mark, a description, a meta and a trailing control.
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/list.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed } from 'vue'

import { useListening } from '@polymorph/vue'
import styles from '@polymorph/recipes/structure/list.module.css'

export interface ListItemProps {
  /**
   * The item whose page or detail is open. At most one per list. It has no effect on an item
   * that is only read, which has no link or button to say it to a screen reader.
   */
  current?: boolean
  /**
   * One supporting line under the title. It wraps and is never clipped.
   */
  description?: string
  /**
   * The item navigates: the title is a link whose target covers the row.
   */
  href?: string
  /**
   * A short trailing fact the application has already formatted: a time, a count.
   */
  meta?: string
  /**
   * The item's name, and the accessible name of its link or button.
   */
  title: string
}

defineOptions({ name: 'ListItem', inheritAttrs: false })

const props = withDefaults(defineProps<ListItemProps>(), { current: false })
const emit = defineEmits<{ navigate: [href: string]; select: [] }>()
defineSlots<{
  leading?: (props: Record<string, never>) => unknown
  trailing?: (props: Record<string, never>) => unknown
}>()
const listening = useListening()
const navigatesHere = computed(
  () =>
    (event: MouseEvent): boolean =>
      !event.defaultPrevented &&
      event.button === 0 &&
      !event.metaKey &&
      !event.ctrlKey &&
      !event.shiftKey &&
      !event.altKey,
)
const route = computed(() => (event: MouseEvent): void => {
  if (props.href === undefined || !listening.navigate || !navigatesHere.value(event)) return
  event.preventDefault()
  emit('navigate', props.href)
})
</script>

<template>
  <li
    :class="styles.item"
    :data-interactive="href !== undefined || listening.select ? '' : undefined"
    :data-current="current && (href !== undefined || listening.select) ? '' : undefined"
  >
    <span v-if="$slots.leading" :class="styles.leading">
      <slot name="leading" />
    </span>
    <span :class="styles.text">
      <!-- link -->
      <a
        v-if="href !== undefined"
        :class="[styles.title, styles.primary]"
        :href="href"
        :aria-current="current ? 'page' : undefined"
        @click="(emit('select'), route($event))"
      >
        {{ title }}
      </a>
      <!-- button -->
      <button
        v-else-if="listening.select"
        :class="[styles.title, styles.primary]"
        type="button"
        :aria-current="current ? 'true' : undefined"
        @click="emit('select')"
      >
        {{ title }}
      </button>
      <span v-else :class="styles.title">
        {{ title }}
      </span>
      <span v-if="description !== undefined" :class="styles.description">
        {{ description }}
      </span>
    </span>
    <span v-if="meta !== undefined" :class="styles.meta">
      {{ meta }}
    </span>
    <span v-if="$slots.trailing" :class="styles.trailing">
      <slot name="trailing" />
    </span>
  </li>
</template>
